BEGIN;
-- CreateEnum
CREATE TYPE "Role" AS ENUM ('resident', 'representative', 'tenant', 'lawful_user', 'provider_employee', 'contact_operator', 'request_specialist', 'inspector', 'meter_specialist', 'accountant', 'organization_admin', 'system_admin');

-- AlterTable
ALTER TABLE "Organization" ADD COLUMN     "blocked" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "version" INTEGER NOT NULL DEFAULT 1;

-- AlterTable
ALTER TABLE "User" ADD COLUMN "organizationId" TEXT;
-- Preserve existing role assignments instead of dropping the column generated by Prisma diff.
ALTER TABLE "User" ALTER COLUMN "roles" DROP DEFAULT;
ALTER TABLE "User" ALTER COLUMN "roles" TYPE "Role"[] USING "roles"::text[]::"Role"[];
UPDATE "User" SET "roles" = ARRAY['resident']::"Role"[] WHERE "roles" IS NULL;
ALTER TABLE "User" ALTER COLUMN "roles" SET DEFAULT ARRAY['resident']::"Role"[];
ALTER TABLE "User" ALTER COLUMN "roles" SET NOT NULL;
ALTER TABLE "User" ADD CONSTRAINT "User_roles_not_empty" CHECK (cardinality("roles") > 0);
ALTER TABLE "User" ADD CONSTRAINT "User_staff_requires_organization" CHECK (
  ("roles" && ARRAY['provider_employee','contact_operator','request_specialist','inspector','meter_specialist','accountant','organization_admin']::"Role"[])
  = ("organizationId" IS NOT NULL)
);
ALTER TABLE "User" ADD CONSTRAINT "User_system_admin_separation" CHECK (
  NOT ('system_admin'::"Role" = ANY("roles") AND "organizationId" IS NOT NULL)
);

-- AddForeignKey
ALTER TABLE "User" ADD CONSTRAINT "User_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
COMMIT;
